mapper.select:
select count(*) from tb_goods
where goods_code = #{goodsCode}
  and goods_no != #{goodsNo}

mapper.insert:
insert into tb_goods (
  goods_no, goods_code, goods_name, category_no, unit,
  safety_qty, unit_price, image_path, use_yn
) values (
  seq_goods.nextval, #{goodsCode}, #{goodsName}, #{categoryNo}, #{unit},
  #{safetyQty}, #{unitPrice}, #{imagePath}, #{useYn}
)
